-- =====================================================================
-- JobPortalFree + CodeXam  |  STARTER DATA  (step 2 of 3)
--
-- Run AFTER database/fresh-supabase-setup.sql, in the same SQL Editor.
-- Safe to run more than once: every row uses ON CONFLICT DO NOTHING / WHERE NOT EXISTS,
-- so it never overwrites anything an admin has already changed.
--
-- Generated from the app's own data files (src/exam/data/sampleData.ts,
-- src/exam/data/starterPack.ts and the DEFAULT_* settings objects).
-- =====================================================================

-- 1) Site settings (public: landing copy, theme, festivals, contacts, sign-up rules)
ON CONFLICT (key) DO NOTHING;

-- 2) CodeXam settings
ON CONFLICT (key) DO NOTHING;

-- 3) Headline ticker
) AS v(t) WHERE NOT EXISTS (SELECT 1 FROM public.headlines h WHERE h.text = v.t);

-- 4) Promo banners
) AS v(i, t, s, l) WHERE NOT EXISTS (SELECT 1 FROM public.promo_banners b WHERE b.title = v.t);

-- 5) Interview preparation library
) AS v(t, c, b, tips) WHERE NOT EXISTS (SELECT 1 FROM public.interview_prep p WHERE p.title = v.t);

-- 6) CodeXam: coding questions

**Input format:** First line contains n and target. Second line contains n integers.

