INSERT INTO public.interview_prep (title, category, content, tips) SELECT v.t, v.c, v.b, v.tips FROM (VALUES
  ('Tell me about yourself', 'General', 'Structure your answer: Present, Past, Future. Start with your current role or studies, mention the most relevant past experience, then connect it to why you want this opportunity.', ARRAY['Keep it under 2 minutes','Focus on professional life','End with why you are here']::text[]),
  ('Why do you want to work here?', 'General', 'Show you researched the company. Name one product, project or value that appeals to you and link it to a skill you bring.', ARRAY['Read the careers page and recent news','Be specific, avoid generic praise','Tie your answer to the role']::text[]),
  ('Common coding interview patterns', 'Technical', 'Focus on arrays and strings, hash maps, two pointers, sliding window, trees, graphs and dynamic programming. Explain your approach before you code.', ARRAY['Practise on LeetCode or HackerRank','Think aloud','Ask clarifying questions first']::text[]),
  ('STAR method for behavioral questions', 'Behavioral', 'Situation: set the context. Task: describe your responsibility. Action: explain what you did. Result: share the outcome, with numbers if possible.', ARRAY['Prepare 5 to 6 STAR stories','Use real examples','Quantify results']::text[]),
  ('Salary negotiation tips', 'HR', 'Research market rates, know your worth and let the employer share their range first. Consider total compensation, not just base pay.', ARRAY['Use public salary data for research','Be confident but respectful','Negotiate after you have an offer']::text[]),
  ('How to explain time and space complexity', 'DSA', 'State the complexity of your solution in Big-O, say which operation dominates, and mention the trade-off you made between time and memory.', ARRAY['Know sorting and searching complexities','Mention best, average and worst cases','Offer an optimisation if asked']::text[]),
  ('The four pillars of OOP', 'OOPS', 'Encapsulation hides internal state, inheritance reuses code, polymorphism lets one interface take many forms and abstraction exposes only what matters. Give one small example of each.', ARRAY['Use a simple real-world example','Mention SOLID if asked about design','Know the difference between overloading and overriding']::text[]),
  ('SQL questions to expect', 'SQL', 'Practise joins, GROUP BY with HAVING, subqueries, window functions, indexes and the difference between WHERE and HAVING.', ARRAY['Write queries by hand, not only in tools','Understand how an index speeds up reads','Know INNER vs LEFT JOIN']::text[]),
  ('Frontend and backend basics', 'Web', 'Be ready to explain the request-response cycle, REST vs GraphQL, HTTP status codes, cookies vs tokens, and how the browser renders a page.', ARRAY['Know common HTTP status codes','Understand CORS at a high level','Be able to describe one project end to end']::text[]),
  ('Processes, threads and deadlocks', 'OS', 'A process has its own memory; threads share memory inside a process. Deadlock needs mutual exclusion, hold and wait, no preemption and circular wait.', ARRAY['Explain context switching','Know one way to avoid deadlock','Mention race conditions']::text[])
