INSERT INTO public.questions (id,title,description,difficulty,default_public_count,default_private_count,languages,time_limit,max_marks,sample_count,sort_order,public_test_cases,private_test_cases) VALUES ('q4','Prime Number Check','Given an integer **n**, print "YES" if prime else "NO".','easy',10,10,'["python","javascript","java","cpp","c"]'::jsonb,15,10,3,3,'[{"id":"tc1","input":"2","expectedOutput":"YES"},{"id":"tc2","input":"3","expectedOutput":"YES"},{"id":"tc3","input":"4","expectedOutput":"NO"},{"id":"tc4","input":"5","expectedOutput":"YES"},{"id":"tc5","input":"6","expectedOutput":"NO"},{"id":"tc6","input":"7","expectedOutput":"YES"},{"id":"tc7","input":"8","expectedOutput":"NO"},{"id":"tc8","input":"9","expectedOutput":"NO"},{"id":"tc9","input":"10","expectedOutput":"NO"},{"id":"tc10","input":"11","expectedOutput":"YES"}]'::jsonb,'[{"id":"ptc1","input":"13","expectedOutput":"YES"},{"id":"ptc2","input":"15","expectedOutput":"NO"},{"id":"ptc3","input":"17","expectedOutput":"YES"},{"id":"ptc4","input":"19","expectedOutput":"YES"},{"id":"ptc5","input":"21","expectedOutput":"NO"},{"id":"ptc6","input":"23","expectedOutput":"YES"},{"id":"ptc7","input":"25","expectedOutput":"NO"},{"id":"ptc8","input":"29","expectedOutput":"YES"},{"id":"ptc9","input":"31","expectedOutput":"YES"},{"id":"ptc10","input":"33","expectedOutput":"NO"}]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id,title,description,difficulty,default_public_count,default_private_count,languages,time_limit,max_marks,sample_count,sort_order,public_test_cases,private_test_cases) VALUES ('q5','Palindrome Check','Given a string, print "YES" if it is a palindrome else "NO".','easy',10,10,'["python","javascript","java","cpp","c"]'::jsonb,15,10,3,4,'[{"id":"tc1","input":"madam","expectedOutput":"YES"},{"id":"tc2","input":"hello","expectedOutput":"NO"},{"id":"tc3","input":"racecar","expectedOutput":"YES"},{"id":"tc4","input":"world","expectedOutput":"NO"},{"id":"tc5","input":"level","expectedOutput":"YES"},{"id":"tc6","input":"noon","expectedOutput":"YES"},{"id":"tc7","input":"python","expectedOutput":"NO"},{"id":"tc8","input":"civic","expectedOutput":"YES"},{"id":"tc9","input":"abc","expectedOutput":"NO"},{"id":"tc10","input":"abba","expectedOutput":"YES"}]'::jsonb,'[{"id":"ptc1","input":"rotor","expectedOutput":"YES"},{"id":"ptc2","input":"test","expectedOutput":"NO"},{"id":"ptc3","input":"aba","expectedOutput":"YES"},{"id":"ptc4","input":"abcba","expectedOutput":"YES"},{"id":"ptc5","input":"xyz","expectedOutput":"NO"},{"id":"ptc6","input":"wow","expectedOutput":"YES"},{"id":"ptc7","input":"noon","expectedOutput":"YES"},{"id":"ptc8","input":"java","expectedOutput":"NO"},{"id":"ptc9","input":"kayak","expectedOutput":"YES"},{"id":"ptc10","input":"radar","expectedOutput":"YES"}]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id,title,description,difficulty,default_public_count,default_private_count,languages,time_limit,max_marks,sample_count,sort_order,public_test_cases,private_test_cases) VALUES ('q6','Sum of N Numbers','Given n, print sum 1+2+..+n.','easy',10,10,'["python","javascript","java","cpp","c"]'::jsonb,15,10,3,5,'[{"id":"tc1","input":"1","expectedOutput":"1"},{"id":"tc2","input":"2","expectedOutput":"3"},{"id":"tc3","input":"3","expectedOutput":"6"},{"id":"tc4","input":"4","expectedOutput":"10"},{"id":"tc5","input":"5","expectedOutput":"15"},{"id":"tc6","input":"10","expectedOutput":"55"},{"id":"tc7","input":"20","expectedOutput":"210"},{"id":"tc8","input":"50","expectedOutput":"1275"},{"id":"tc9","input":"100","expectedOutput":"5050"},{"id":"tc10","input":"7","expectedOutput":"28"}]'::jsonb,'[{"id":"ptc1","input":"11","expectedOutput":"66"},{"id":"ptc2","input":"13","expectedOutput":"91"},{"id":"ptc3","input":"15","expectedOutput":"120"},{"id":"ptc4","input":"17","expectedOutput":"153"},{"id":"ptc5","input":"25","expectedOutput":"325"},{"id":"ptc6","input":"30","expectedOutput":"465"},{"id":"ptc7","input":"40","expectedOutput":"820"},{"id":"ptc8","input":"60","expectedOutput":"1830"},{"id":"ptc9","input":"70","expectedOutput":"2485"},{"id":"ptc10","input":"99","expectedOutput":"4950"}]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id,title,description,difficulty,default_public_count,default_private_count,languages,time_limit,max_marks,sample_count,sort_order,public_test_cases,private_test_cases) VALUES ('q7','Valid Parentheses','Given a string of brackets () [] {}, print "YES" if balanced else "NO".','easy',10,10,'["python","javascript","java","cpp","c"]'::jsonb,20,10,3,6,'[{"id":"tc1","input":"()","expectedOutput":"YES"},{"id":"tc2","input":"()[]{}","expectedOutput":"YES"},{"id":"tc3","input":"(]","expectedOutput":"NO"},{"id":"tc4","input":"([)]","expectedOutput":"NO"},{"id":"tc5","input":"{[]}","expectedOutput":"YES"},{"id":"tc6","input":"","expectedOutput":"YES"},{"id":"tc7","input":"((()))","expectedOutput":"YES"},{"id":"tc8","input":"([)","expectedOutput":"NO"},{"id":"tc9","input":"[{()}]","expectedOutput":"YES"},{"id":"tc10","input":"{{}}","expectedOutput":"YES"}]'::jsonb,'[{"id":"ptc1","input":"(((","expectedOutput":"NO"},{"id":"ptc2","input":"[[]]","expectedOutput":"YES"},{"id":"ptc3","input":"((","expectedOutput":"NO"},{"id":"ptc4","input":"{}","expectedOutput":"YES"},{"id":"ptc5","input":"([])","expectedOutput":"YES"},{"id":"ptc6","input":"[(])","expectedOutput":"NO"},{"id":"ptc7","input":"((()","expectedOutput":"NO"},{"id":"ptc8","input":"()()","expectedOutput":"YES"},{"id":"ptc9","input":"){","expectedOutput":"NO"},{"id":"ptc10","input":")(","expectedOutput":"NO"}]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id,title,description,difficulty,default_public_count,default_private_count,languages,time_limit,max_marks,sample_count,sort_order,public_test_cases,private_test_cases) VALUES ('q8','Count Vowels','Count vowels (aeiou, case-insensitive) in a string.','easy',10,10,'["python","javascript","java","cpp","c"]'::jsonb,15,10,3,7,'[{"id":"tc1","input":"hello","expectedOutput":"2"},{"id":"tc2","input":"world","expectedOutput":"1"},{"id":"tc3","input":"aeiou","expectedOutput":"5"},{"id":"tc4","input":"xyz","expectedOutput":"0"},{"id":"tc5","input":"programming","expectedOutput":"3"},{"id":"tc6","input":"beautiful","expectedOutput":"5"},{"id":"tc7","input":"rhythm","expectedOutput":"0"},{"id":"tc8","input":"queue","expectedOutput":"4"},{"id":"tc9","input":"education","expectedOutput":"5"},{"id":"tc10","input":"sky","expectedOutput":"0"}]'::jsonb,'[{"id":"ptc1","input":"apple","expectedOutput":"2"},{"id":"ptc2","input":"banana","expectedOutput":"3"},{"id":"ptc3","input":"grape","expectedOutput":"2"},{"id":"ptc4","input":"orange","expectedOutput":"3"},{"id":"ptc5","input":"melon","expectedOutput":"2"},{"id":"ptc6","input":"strawberry","expectedOutput":"2"},{"id":"ptc7","input":"kiwi","expectedOutput":"2"},{"id":"ptc8","input":"pear","expectedOutput":"2"},{"id":"ptc9","input":"plum","expectedOutput":"1"},{"id":"ptc10","input":"peach","expectedOutput":"2"}]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id,title,description,difficulty,default_public_count,default_private_count,languages,time_limit,max_marks,sample_count,sort_order,public_test_cases,private_test_cases) VALUES ('q9','Factorial','Given n, print n!.','easy',10,10,'["python","javascript","java","cpp","c"]'::jsonb,15,10,3,8,'[{"id":"tc1","input":"0","expectedOutput":"1"},{"id":"tc2","input":"1","expectedOutput":"1"},{"id":"tc3","input":"2","expectedOutput":"2"},{"id":"tc4","input":"3","expectedOutput":"6"},{"id":"tc5","input":"4","expectedOutput":"24"},{"id":"tc6","input":"5","expectedOutput":"120"},{"id":"tc7","input":"6","expectedOutput":"720"},{"id":"tc8","input":"7","expectedOutput":"5040"},{"id":"tc9","input":"8","expectedOutput":"40320"},{"id":"tc10","input":"9","expectedOutput":"362880"}]'::jsonb,'[{"id":"ptc1","input":"10","expectedOutput":"3628800"},{"id":"ptc2","input":"11","expectedOutput":"39916800"},{"id":"ptc3","input":"12","expectedOutput":"479001600"},{"id":"ptc4","input":"3","expectedOutput":"6"},{"id":"ptc5","input":"4","expectedOutput":"24"},{"id":"ptc6","input":"5","expectedOutput":"120"},{"id":"ptc7","input":"6","expectedOutput":"720"},{"id":"ptc8","input":"7","expectedOutput":"5040"},{"id":"ptc9","input":"8","expectedOutput":"40320"},{"id":"ptc10","input":"9","expectedOutput":"362880"}]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id,title,description,difficulty,default_public_count,default_private_count,languages,time_limit,max_marks,sample_count,sort_order,public_test_cases,private_test_cases) VALUES ('q10','Anagram Check','Two strings on two lines. Print "YES" if anagrams.','medium',10,10,'["python","javascript","java","cpp","c"]'::jsonb,25,10,3,9,'[{"id":"tc1","input":"listen\nsilent","expectedOutput":"YES"},{"id":"tc2","input":"hello\nworld","expectedOutput":"NO"},{"id":"tc3","input":"evil\nvile","expectedOutput":"YES"},{"id":"tc4","input":"cat\nact","expectedOutput":"YES"},{"id":"tc5","input":"dog\ngod","expectedOutput":"YES"},{"id":"tc6","input":"rat\ntar","expectedOutput":"YES"},{"id":"tc7","input":"abc\ncba","expectedOutput":"YES"},{"id":"tc8","input":"abcd\ndcba","expectedOutput":"YES"},{"id":"tc9","input":"a\nb","expectedOutput":"NO"},{"id":"tc10","input":"fluster\nrestful","expectedOutput":"YES"}]'::jsonb,'[{"id":"ptc1","input":"night\nthing","expectedOutput":"YES"},{"id":"ptc2","input":"stop\ntops","expectedOutput":"YES"},{"id":"ptc3","input":"save\nvase","expectedOutput":"YES"},{"id":"ptc4","input":"name\nmean","expectedOutput":"YES"},{"id":"ptc5","input":"xyz\nxyy","expectedOutput":"NO"},{"id":"ptc6","input":"aabb\nabab","expectedOutput":"YES"},{"id":"ptc7","input":"abc\nabd","expectedOutput":"NO"},{"id":"ptc8","input":"silent\nlisten","expectedOutput":"YES"},{"id":"ptc9","input":"triangle\nintegral","expectedOutput":"YES"},{"id":"ptc10","input":"apple\npapel","expectedOutput":"YES"}]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id,title,description,difficulty,default_public_count,default_private_count,languages,time_limit,max_marks,sample_count,sort_order,public_test_cases,private_test_cases) VALUES ('q11','Fibonacci Nth Term','Given n, print nth Fibonacci (F(0)=0, F(1)=1).','medium',10,10,'["python","javascript","java","cpp","c"]'::jsonb,25,10,3,10,'[{"id":"tc1","input":"0","expectedOutput":"0"},{"id":"tc2","input":"1","expectedOutput":"1"},{"id":"tc3","input":"2","expectedOutput":"1"},{"id":"tc4","input":"3","expectedOutput":"2"},{"id":"tc5","input":"4","expectedOutput":"3"},{"id":"tc6","input":"5","expectedOutput":"5"},{"id":"tc7","input":"6","expectedOutput":"8"},{"id":"tc8","input":"7","expectedOutput":"13"},{"id":"tc9","input":"8","expectedOutput":"21"},{"id":"tc10","input":"9","expectedOutput":"34"}]'::jsonb,'[{"id":"ptc1","input":"10","expectedOutput":"55"},{"id":"ptc2","input":"12","expectedOutput":"144"},{"id":"ptc3","input":"15","expectedOutput":"610"},{"id":"ptc4","input":"20","expectedOutput":"6765"},{"id":"ptc5","input":"25","expectedOutput":"75025"},{"id":"ptc6","input":"30","expectedOutput":"832040"},{"id":"ptc7","input":"11","expectedOutput":"89"},{"id":"ptc8","input":"13","expectedOutput":"233"},{"id":"ptc9","input":"14","expectedOutput":"377"},{"id":"ptc10","input":"18","expectedOutput":"2584"}]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.questions (id,title,description,difficulty,default_public_count,default_private_count,languages,time_limit,max_marks,sample_count,sort_order,public_test_cases,private_test_cases) VALUES ('q12','Second Largest Element','First line n, second line n integers. Print second largest distinct.','medium',10,10,'["python","javascript","java","cpp","c"]'::jsonb,25,10,3,11,'[{"id":"tc1","input":"5\n1 2 3 4 5","expectedOutput":"4"},{"id":"tc2","input":"5\n5 5 4 3 2","expectedOutput":"4"},{"id":"tc3","input":"3\n10 20 30","expectedOutput":"20"},{"id":"tc4","input":"3\n1 1 2","expectedOutput":"1"},{"id":"tc5","input":"4\n7 7 7 6","expectedOutput":"6"},{"id":"tc6","input":"3\n100 99 98","expectedOutput":"99"},{"id":"tc7","input":"8\n3 1 4 1 5 9 2 6","expectedOutput":"6"},{"id":"tc8","input":"3\n8 8 7","expectedOutput":"7"},{"id":"tc9","input":"2\n1 2","expectedOutput":"1"},{"id":"tc10","input":"5\n9 1 9 2 9","expectedOutput":"2"}]'::jsonb,'[{"id":"ptc1","input":"5\n10 10 9 8 7","expectedOutput":"9"},{"id":"ptc2","input":"5\n5 4 3 2 1","expectedOutput":"4"},{"id":"ptc3","input":"4\n11 22 33 44","expectedOutput":"33"},{"id":"ptc4","input":"5\n6 6 6 5 5","expectedOutput":"5"},{"id":"ptc5","input":"3\n100 50 25","expectedOutput":"50"},{"id":"ptc6","input":"5\n1 3 5 7 9","expectedOutput":"7"},{"id":"ptc7","input":"5\n2 4 6 8 10","expectedOutput":"8"},{"id":"ptc8","input":"4\n12 15 18 21","expectedOutput":"18"},{"id":"ptc9","input":"5\n7 3 5 1 9","expectedOutput":"7"},{"id":"ptc10","input":"5\n6 2 8 4 10","expectedOutput":"8"}]'::jsonb) ON CONFLICT (id) DO NOTHING;
