INSERT INTO public.mcq_questions (id,question,options,correct_index,category,difficulty,marks,explanation) VALUES ('m1','What is the time complexity of binary search on a sorted array?','["O(n)","O(log n)","O(n log n)","O(1)"]'::jsonb,1,'Algorithms','easy',1,'Binary search halves the search space each step, giving O(log n).') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mcq_questions (id,question,options,correct_index,category,difficulty,marks,explanation) VALUES ('m2','Which data structure uses FIFO (First-In-First-Out) order?','["Stack","Queue","Tree","Graph"]'::jsonb,1,'Data Structures','easy',1,'Queues process elements in the order they arrive (FIFO).') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mcq_questions (id,question,options,correct_index,category,difficulty,marks,explanation) VALUES ('m3','Which data structure uses LIFO (Last-In-First-Out) order?','["Queue","Stack","Heap","Linked List"]'::jsonb,1,'Data Structures','easy',1,'Stacks push and pop from the same end (LIFO).') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mcq_questions (id,question,options,correct_index,category,difficulty,marks,explanation) VALUES ('m4','What is the worst-case time complexity of Quick Sort?','["O(n log n)","O(n)","O(n^2)","O(log n)"]'::jsonb,2,'Algorithms','medium',1,'Quick sort degrades to O(n^2) when pivots are poorly chosen.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mcq_questions (id,question,options,correct_index,category,difficulty,marks,explanation) VALUES ('m5','Which of the following is NOT a linear data structure?','["Array","Linked List","Tree","Queue"]'::jsonb,2,'Data Structures','easy',1,'Trees are hierarchical, not linear.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mcq_questions (id,question,options,correct_index,category,difficulty,marks,explanation) VALUES ('m6','Which sorting algorithm is stable and has O(n log n) worst case?','["Quick Sort","Merge Sort","Heap Sort","Selection Sort"]'::jsonb,1,'Algorithms','medium',1,'Merge sort preserves equal-key ordering and guarantees O(n log n).') ON CONFLICT (id) DO NOTHING;
